/* 5173 Gold: real routed campaigns page */
.dp-campaigns-page {
  --dp-bg: #F7F8FB;
  --dp-white: #FFFFFF;
  --dp-alt: #F1F3F7;
  --dp-navy: #071B2F;
  --dp-navy-2: #0B1F33;
  --dp-gold: #BFA46A;
  --dp-gold-deep: #B8963E;
  --dp-border: rgba(7, 27, 47, 0.08);
  --dp-muted: rgba(7, 27, 47, 0.68);
  --dp-soft: rgba(7, 27, 47, 0.52);
  min-height: 100vh;
  background: var(--dp-bg);
  color: var(--dp-navy);
  font-family: Inter, sans-serif;
}

.dp-campaigns-page * {
  box-sizing: border-box;
}

.dp-campaigns-header {
  position: sticky;
  top: 0;
  z-index: 50;
  display: grid;
  grid-template-columns: 1fr;
  gap: 12px;
  padding: 14px 20px;
  border-bottom: 1px solid var(--dp-border);
  background: rgba(255, 255, 255, 0.92);
  -webkit-backdrop-filter: blur(16px);
  backdrop-filter: blur(16px);
}

.dp-campaigns-brand {
  color: var(--dp-navy);
  font-size: 14px;
  font-weight: 800;
  text-decoration: none;
}

.dp-campaigns-header nav,
.dp-campaigns-header > div,
.dp-campaigns-cta-row {
  display: flex;
  gap: 10px;
  align-items: center;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.dp-campaigns-header a {
  color: var(--dp-muted);
  font-size: 12px;
  font-weight: 700;
  text-decoration: none;
  white-space: nowrap;
}

.dp-campaigns-primary,
.dp-campaigns-secondary,
.dp-campaigns-gold {
  min-height: 46px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border-radius: 10px;
  padding: 0 16px;
  border: 1px solid transparent;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  text-decoration: none;
  transition: transform 220ms ease, opacity 220ms ease, border-color 220ms ease;
  white-space: nowrap;
}

.dp-campaigns-primary {
  background: var(--dp-navy);
  color: #FFFFFF;
}

.dp-campaigns-secondary {
  background: #FFFFFF;
  color: var(--dp-navy);
  border-color: rgba(7, 27, 47, 0.18);
}

.dp-campaigns-gold {
  background: var(--dp-gold);
  color: var(--dp-navy);
}

.dp-campaigns-primary:hover,
.dp-campaigns-secondary:hover,
.dp-campaigns-gold:hover,
.dp-moment-scroller article:hover,
.dp-proof-grid article:hover {
  transform: translateY(-2px);
  opacity: 0.96;
}

.dp-campaigns-hero,
.dp-campaigns-section,
.dp-final-campaign-cta,
.dp-campaign-footer {
  width: min(1180px, calc(100% - 40px));
  margin-inline: auto;
}

.dp-campaigns-hero,
.dp-campaigns-section {
  padding-block: 56px;
}

.dp-campaigns-hero {
  display: grid;
  gap: 28px;
  align-items: center;
}

.dp-campaigns-eyebrow {
  margin: 0 0 12px;
  color: var(--dp-gold-deep);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.dp-campaigns-page h1,
.dp-campaigns-page h2,
.dp-campaigns-page h3,
.dp-campaigns-page p {
  margin: 0;
}

.dp-campaigns-page h1 {
  max-width: 760px;
  font-size: clamp(42px, 7vw, 82px);
  font-weight: 700;
  letter-spacing: -0.05em;
  line-height: 0.98;
}

.dp-campaigns-page h2 {
  max-width: 720px;
  font-size: clamp(30px, 4vw, 52px);
  font-weight: 700;
  letter-spacing: -0.04em;
  line-height: 1.04;
}

.dp-campaigns-page h3 {
  font-size: 22px;
  font-weight: 750;
  letter-spacing: -0.03em;
  line-height: 1.1;
}

.dp-campaigns-page p {
  max-width: 680px;
  color: var(--dp-muted);
  font-size: 16px;
  line-height: 1.7;
}

.dp-campaigns-hero p,
.dp-campaigns-section > p,
.dp-campaigns-how p,
.dp-campaigns-preview p {
  margin-top: 18px;
}

.dp-campaigns-cta-row {
  margin-top: 24px;
  flex-wrap: wrap;
}

.dp-campaigns-visual {
  position: relative;
  margin: 0;
}

.dp-campaigns-visual img,
.dp-moment-scroller img,
.dp-proof-grid img,
.dp-brand-network-showcase img {
  width: 100%;
  object-fit: cover;
  display: block;
}

.dp-campaigns-visual img {
  aspect-ratio: 4 / 5;
  border-radius: 18px;
  border: 1px solid var(--dp-border);
}

.dp-campaigns-visual figcaption {
  position: absolute;
  left: 16px;
  right: 16px;
  bottom: 16px;
  display: grid;
  gap: 6px;
  padding: 14px;
  border: 1px solid rgba(255, 255, 255, 0.38);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.88);
  -webkit-backdrop-filter: blur(16px);
  backdrop-filter: blur(16px);
}

.dp-campaigns-visual figcaption strong {
  color: var(--dp-navy);
  font-size: 13px;
}

.dp-campaigns-visual figcaption span {
  color: var(--dp-muted);
  font-size: 12px;
  line-height: 1.35;
}

.dp-moment-scroller,
.dp-campaign-type-tabs,
.dp-metric-chip-row,
.dp-brand-network-showcase {
  display: flex;
  gap: 14px;
  margin-top: 24px;
  overflow-x: auto;
  padding-bottom: 8px;
  scroll-snap-type: x proximity;
  -webkit-overflow-scrolling: touch;
}

.dp-moment-scroller article {
  flex: 0 0 220px;
  display: grid;
  gap: 12px;
  scroll-snap-align: start;
}

.dp-moment-scroller img {
  aspect-ratio: 4 / 3;
  border-radius: 18px;
  border: 1px solid var(--dp-border);
}

.dp-moment-scroller strong,
.dp-metric-chip-row span {
  color: var(--dp-navy);
  font-size: 14px;
  font-weight: 750;
}

.dp-campaigns-how {
  display: grid;
  gap: 28px;
}

.dp-campaigns-how ol {
  display: grid;
  gap: 0;
  margin: 0;
  padding: 0;
  list-style: none;
  border-top: 1px solid var(--dp-border);
}

.dp-campaigns-how li {
  display: grid;
  grid-template-columns: 40px 1fr;
  gap: 10px;
  padding: 16px 0;
  border-bottom: 1px solid var(--dp-border);
}

.dp-campaigns-how li span {
  color: var(--dp-gold-deep);
  font-size: 12px;
  font-weight: 800;
}

.dp-campaigns-how li strong {
  color: var(--dp-navy);
}

.dp-campaigns-how li p {
  grid-column: 2;
  margin-top: 2px;
  font-size: 14px;
}

.dp-campaign-type-tabs button,
.dp-metric-chip-row span {
  flex: 0 0 auto;
  min-height: 40px;
  border: 1px solid var(--dp-border);
  border-radius: 10px;
  background: #FFFFFF;
  padding: 0 14px;
  color: var(--dp-muted);
  font-size: 12px;
  font-weight: 800;
}

.dp-campaign-type-tabs button[aria-selected="true"] {
  border-color: var(--dp-navy);
  background: var(--dp-navy);
  color: #FFFFFF;
}

.dp-campaign-type-panel,
.dp-campaigns-preview article,
.dp-proof-grid article,
.dp-launch-section form,
.dp-campaign-faq article,
.dp-brand-network-showcase article,
.dp-two-sided-faq,
.dp-final-campaign-cta {
  border: 1px solid var(--dp-border);
  border-radius: 18px;
  background: #FFFFFF;
  box-shadow: 0 18px 48px rgba(7, 27, 47, 0.06);
}

.dp-campaign-type-panel {
  display: grid;
  gap: 22px;
  margin-top: 18px;
  padding: 20px;
}

.dp-campaign-type-panel p,
.dp-campaign-type-panel strong {
  margin-top: 12px;
}

.dp-campaign-type-panel ul {
  display: grid;
  gap: 10px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.dp-campaign-type-panel li {
  display: flex;
  gap: 8px;
  align-items: center;
  color: var(--dp-muted);
  font-size: 14px;
}

.dp-campaigns-preview,
.dp-launch-section,
.dp-campaign-faq {
  display: grid;
  gap: 24px;
}

.dp-campaigns-preview article,
.dp-launch-section form {
  padding: 20px;
}

.dp-campaigns-preview article {
  display: grid;
  gap: 10px;
}

.dp-campaigns-preview article > p {
  color: var(--dp-gold-deep);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.dp-campaigns-preview article span,
.dp-campaigns-preview article small {
  color: var(--dp-muted);
  font-size: 13px;
}

.dp-campaigns-preview article div {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 6px;
}

.dp-campaigns-preview article button {
  min-height: 42px;
  border: 1px solid var(--dp-border);
  border-radius: 10px;
  background: #FFFFFF;
  padding: 0 12px;
  color: var(--dp-navy);
  font-weight: 800;
}

.dp-proof-grid {
  display: grid;
  gap: 16px;
  margin-top: 24px;
}

.dp-proof-grid article {
  position: relative;
  overflow: hidden;
}

.dp-proof-grid img {
  aspect-ratio: 3 / 2;
}

.dp-proof-grid svg {
  margin: 16px 16px 8px;
  color: var(--dp-gold-deep);
}

.dp-proof-grid h3,
.dp-proof-grid p {
  padding-inline: 16px;
}

.dp-proof-grid p {
  padding-bottom: 18px;
  font-size: 14px;
}

.dp-brand-network-showcase article {
  flex: 0 0 260px;
  overflow: hidden;
  scroll-snap-align: start;
}

.dp-brand-network-showcase img {
  aspect-ratio: 4 / 3;
}

.dp-brand-network-showcase div {
  display: grid;
  gap: 8px;
  padding: 16px;
}

.dp-brand-network-showcase strong {
  color: var(--dp-navy);
}

.dp-brand-network-showcase p {
  font-size: 14px;
}

.dp-launch-section form {
  display: grid;
  gap: 14px;
}

.dp-launch-section label {
  display: grid;
  gap: 7px;
  color: var(--dp-soft);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.11em;
  text-transform: uppercase;
}

.dp-launch-section input,
.dp-launch-section select,
.dp-launch-section textarea {
  width: 100%;
  min-height: 46px;
  border: 1px solid rgba(7, 27, 47, 0.14);
  border-radius: 10px;
  background: #FFFFFF;
  padding: 11px 12px;
  color: var(--dp-navy);
  font: 500 14px/1.45 Inter, sans-serif;
  letter-spacing: 0;
  text-transform: none;
}

.dp-launch-section textarea {
  min-height: 110px;
  resize: vertical;
}

.dp-launch-section small,
.dp-campaign-success {
  display: block;
  margin-top: 14px;
  color: var(--dp-muted);
  font-size: 13px;
  line-height: 1.5;
}

.dp-campaign-faq article {
  margin-bottom: 10px;
  padding: 0;
  overflow: hidden;
}

.dp-campaign-faq article button,
.dp-faq-item button {
  width: 100%;
  min-height: 52px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border: 0;
  background: transparent;
  padding: 14px 16px;
  color: var(--dp-navy);
  font: 800 14px/1.3 Inter, sans-serif;
  text-align: left;
}

.dp-campaign-faq article p,
.dp-faq-item p {
  padding: 0 16px 16px;
  font-size: 14px;
}

.dp-two-sided-faq {
  margin-top: 20px;
  padding: 12px;
}

.dp-faq-mode-row {
  display: flex;
  gap: 8px;
  margin-bottom: 8px;
}

.dp-faq-mode-row button {
  min-height: 38px;
  border: 1px solid var(--dp-border);
  border-radius: 10px;
  background: #FFFFFF;
  padding: 0 12px;
  color: var(--dp-muted);
  font-weight: 800;
}

.dp-faq-mode-row button[aria-selected="true"] {
  background: var(--dp-navy);
  color: #FFFFFF;
}

.dp-final-campaign-cta {
  display: grid;
  gap: 18px;
  margin-block: 56px;
  padding: 28px;
  background: linear-gradient(135deg, #071B2F 0%, #0B1F33 100%);
  color: #FFFFFF;
}

.dp-final-campaign-cta p {
  color: rgba(255, 255, 255, 0.78);
}

.dp-campaign-footer {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding-block: 32px 52px;
  border-top: 1px solid var(--dp-border);
  color: var(--dp-muted);
  font-size: 13px;
}

.dp-campaign-footer a {
  color: var(--dp-navy);
  font-weight: 800;
  text-decoration: none;
}

@media (min-width: 760px) {
  .dp-campaigns-header {
    grid-template-columns: auto 1fr auto;
    align-items: center;
    padding-inline: 28px;
  }

  .dp-campaigns-header nav {
    justify-content: center;
  }

  .dp-campaigns-hero,
  .dp-campaigns-how,
  .dp-campaigns-preview,
  .dp-launch-section,
  .dp-campaign-faq {
    grid-template-columns: minmax(0, 1fr) minmax(320px, 0.82fr);
  }

  .dp-campaigns-hero,
  .dp-campaigns-section {
    padding-block: 76px;
  }

  .dp-campaign-type-panel {
    grid-template-columns: minmax(0, 1fr) minmax(220px, 0.6fr) auto;
    align-items: center;
    padding: 28px;
  }

  .dp-proof-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

/* 5173 global quick search */
.dp-global-search-trigger,
.dp-global-search-icon-button,
.dp-map-global-search-button {
  font-family: Inter, sans-serif;
  color: #0B1F33;
  border: 1px solid rgba(11, 31, 51, 0.08);
  background: #FFFFFF;
  box-shadow: 0 10px 28px rgba(11, 31, 51, 0.07);
  transition: transform 180ms ease, border-color 180ms ease, color 180ms ease, box-shadow 180ms ease;
}

.dp-product-shell-search-button {
  position: fixed;
  right: 16px;
  top: 16px;
  z-index: 1300;
  display: inline-flex;
  min-height: 40px;
  align-items: center;
  gap: 8px;
  border: 1px solid rgba(11, 31, 51, 0.08);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.96);
  padding: 0 13px;
  color: #0B1F33;
  font-family: Inter, sans-serif;
  font-size: 11px;
  font-weight: 700;
